table inventory-table"><thead><tr><th>Item</th><th>Category</th><th>Variants</th><th>Price Range</th><th>Stock</th><th>Availability</th><th>Actions</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><strong><?php echo htmlspecialchars($item['name']); ?></strong></td><td><?php echo htmlspecialchars($item['category_name']); ?></td><td><?php echo (int) $item['variant_count']; ?> <?php echo (int) $item['variant_count'] === 1 ? 'size' : 'sizes'; ?></td><td>&#8369;<?php echo number_format((float) $item['min_price'], 2); ?><?php if ((float) $item['min_price'] !== (float) $item['max_price']): ?> &ndash; &#8369;<?php echo number_format((float) $item['max_price'], 2); ?><?php endif; ?></td><td><?php echo (int) $item['total_quantity']; ?> total</td><td><span class="availability-badge">View variants</span></td><td class="actions-cell"><button class="dots-button" type="button" aria-label="Actions for <?php echo htmlspecialchars($item['name']); ?>" aria-expanded="false">&#8942;</button><div class="action-menu"><button type="button" data-item-action="view" data-item-id="<?php echo (int) $item['id']; ?>" data-item-variants="<?php echo htmlspecialchars(json_encode($variantLookup[$item['id']] ?? [], JSON_HEX_APOS | JSON_HEX_QUOT), ENT_QUOTES); ?>" data-item-name="<?php echo htmlspecialchars($item['name'], ENT_QUOTES); ?>" data-item-category="<?php echo htmlspecialchars($item['category_name'], ENT_QUOTES); ?>" data-item-description="<?php echo htmlspecialchars($item['description'], ENT_QUOTES); ?>">View Item</button><button type="button" data-item-action="edit" data-item-id="<?php echo (int) $item['id']; ?>" data-item-name="<?php echo htmlspecialchars($item['name'], ENT_QUOTES); ?>" data-item-category-id="<?php echo (int) $item['category_id']; ?>" data-item-description="<?php echo htmlspecialchars($item['description'], ENT_QUOTES); ?>" data-item-variants="<?php echo htmlspecialchars(json_encode($variantLookup[$item['id']] ?? [], JSON_HEX_APOS | JSON_HEX_QUOT), ENT_QUOTES); ?>">Edit Item</button><button class="danger-text" type="button" data-item-action="delete" data-item-id="<?php echo (int) $item['id']; ?>">Delete Item</button></div></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="7" class="empty-state">No inventory items found.</td></tr><?php endif; ?></tbody></table></div><div class="list-footer"><span>Showing <?php echo $start; ?>&ndash;<?php echo $end; ?> of <?php echo $totalItems; ?> items</span><?php if ($totalPages > 1 && $show !== 'all'): ?><nav class="pagination" aria-label="Inventory pages"><?php $previous = $queryParams; $previous['page'] = max(1, $page - 1); ?><a class="page-link <?php echo $page === 1 ? 'disabled' : ''; ?>" href="?<?php echo http_build_query($previous); ?>">Previous</a><?php for ($pageNumber = 1; $pageNumber <= $totalPages; $pageNumber++): $pageQuery = $queryParams; $pageQuery['page'] = $pageNumber; ?><a class="page-link <?php echo $pageNumber === $page ? 'current' : ''; ?>" href="?<?php echo http_build_query($pageQuery); ?>"><?php echo $pageNumber; ?></a><?php endfor; $next = $queryParams; $next['page'] = min($totalPages, $page + 1); ?><a class="page-link <?php echo $page === $totalPages ? 'disabled' : ''; ?>" href="?<?php echo http_build_query($next); ?>">Next</a></nav><?php endif; ?></div></section>

